          "claim": "travel2's POST to seat left_tickets takes about 4.9s at the client, while seat's server span takes about 17ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) AS n, round(approx_quantile(c.duration,0.5)/1e6,1) AS client_p50_ms, round(approx_quantile(c.duration,0.95)/1e6,1) AS client_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.service_name='ts-basic-service' GROUP BY ALL",
