          "claim": "travel-plan's cheapest, minStation and quickest server spans take 10s at the median and up to 60s at p95."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, round(approx_quantile(duration,0.5)/1e6,1) AS p50_ms, round(approx_quantile(duration,0.95)/1e6,1) AS p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' AND span_name LIKE 'POST%' GROUP BY ALL",
